mapper.sql:
WHERE a.delete_yn = 'N'

  AND a.status = #{search.status}


  AND a.admin_group_id = #{search.adminGroupId}


  AND a.email_hash = #{search.emailExact}


  AND (a.login_id        LIKE CONCAT('%', #{search.keyword}, '%')
    OR a.department_name LIKE CONCAT('%', #{search.keyword}, '%'))

mapper.select:
SELECT COUNT(1)
  FROM tb_admin
 WHERE login_id  = #{loginId}
   AND delete_yn = 'N'

  AND admin_id <> #{excludeAdminId}

SELECT COUNT(1)
  FROM tb_admin
 WHERE email_hash = #{emailHash}
   AND delete_yn  = 'N'

  AND admin_id <> #{excludeAdminId}

mapper.update:
UPDATE tb_admin
   SET captcha_required_yn = #{yn}
 WHERE login_id  = #{loginId}
   AND delete_yn = 'N'

mapper.select:
SELECT password_hash
  FROM tb_admin_password_history
 WHERE admin_id = #{adminId}
 ORDER BY changed_at DESC
 LIMIT #{limit}

SELECT COUNT(*)
  FROM tb_admin_withdraw
 WHERE retention_expire_at <= #{now}
